/**
 * The 1v1 arena, as data. Metres, world space, y up. Every box is
 * { x, y, z, w, h, d } — centre and full size — plus optional flags:
 *   floor: the ground slab   wall: a perimeter wall
 *
 * Point-symmetric about the origin, (x, z) -> (-x, -z), so both spawns see the
 * same arena. Spawn A faces -z (yaw 0), spawn B faces +z (yaw PI).
 *
 * Height levels (box tops): ground 0, steps 0.6 / 0.75 / 1.2 / 1.8, cover 1.2 /
 * 1.6, ledges 1.5, high deck 2.4, pillars 4.
 */
const SIZE = 30;
const H = SIZE / 2;

/** One side of the arena; the other is generated by point symmetry. */
const HALF = [
  // high deck with a staircase rising toward the centre
  { x: 9, y: 1.2, z: -6, w: 4, h: 2.4, d: 4 },
  { x: 6.5, y: 0.9, z: -6, w: 1, h: 1.8, d: 4 },
  { x: 5.5, y: 0.6, z: -6, w: 1, h: 1.2, d: 4 },
  { x: 4.5, y: 0.3, z: -6, w: 1, h: 0.6, d: 4 },
  // ledge with one step
  { x: 9, y: 0.75, z: 4, w: 5, h: 1.5, d: 6 },
  { x: 6, y: 0.375, z: 4, w: 1, h: 0.75, d: 3 },
  // crouch cover near the spawn lane, and a tall-ish side cover
  { x: 4, y: 0.6, z: 8, w: 3, h: 1.2, d: 1 },
  { x: -5, y: 0.8, z: 1.5, w: 1, h: 1.6, d: 3 },
  // pillar breaking the spawn-to-centre sight line
  { x: 0, y: 2, z: 7, w: 1.5, h: 4, d: 1.5 },
];

const mirror = (b) => ({ ...b, x: b.x === 0 ? 0 : -b.x, z: b.z === 0 ? 0 : -b.z });

export const ARENA = {
  size: SIZE,
  boxes: [
    { x: 0, y: -0.25, z: 0, w: SIZE, h: 0.5, d: SIZE, floor: true },
    { x: 0, y: 2.5, z: H - 0.5, w: SIZE, h: 5, d: 1, wall: true },
    { x: 0, y: 2.5, z: -(H - 0.5), w: SIZE, h: 5, d: 1, wall: true },
    { x: H - 0.5, y: 2.5, z: 0, w: 1, h: 5, d: SIZE - 2, wall: true },
    { x: -(H - 0.5), y: 2.5, z: 0, w: 1, h: 5, d: SIZE - 2, wall: true },
    // the centre block is its own twin
    { x: 0, y: 0.6, z: 0, w: 2, h: 1.2, d: 4 },
    ...HALF,
    ...HALF.map(mirror),
  ],
  spawns: [
    { x: 0, y: 0, z: 12, yaw: 0 },
    { x: 0, y: 0, z: -12, yaw: Math.PI },
  ],
};

const EPS = 1e-6;
const same = (a, b) => Math.abs(a - b) < EPS;

/** Returns a list of problems; an empty list means the layout is usable. */
export function validateLayout(layout) {
  const errors = [];
  const h = layout.size / 2;
  if (layout.spawns?.length !== 2) errors.push('need exactly 2 spawns');
  for (const b of layout.boxes) {
    if (Math.abs(b.x) + b.w / 2 > h + EPS || Math.abs(b.z) + b.d / 2 > h + EPS)
      errors.push(`box at ${b.x},${b.z} is outside the arena`);
    const twin = layout.boxes.find(
      (o) => same(o.x, -b.x) && same(o.z, -b.z) && same(o.y, b.y) && same(o.w, b.w) && same(o.h, b.h) && same(o.d, b.d)
    );
    if (!twin) errors.push(`box at ${b.x},${b.z} has no symmetric twin`);
  }
  if (layout.boxes.filter((b) => b.wall).length !== 4) errors.push('need 4 perimeter walls');
  if (layout.spawns?.length === 2) {
    const [a, c] = layout.spawns;
    if (Math.hypot(a.x - c.x, a.z - c.z) < 24) errors.push('spawns closer than 24 m');
  }
  return errors;
}
